mapper.update:
UPDATE TB_CHCF002
   SET ATTR_VAL  = #{v.attrVal},
       ATTR_STAT = #{v.attrStat},
       UPD_DT    = NOW()
 WHERE CP_ID     = #{v.cpId}
   AND CS_ID     = #{v.csId}
   AND COMP_NM   = #{v.compNm}
   AND COMP_INST = #{v.compInst}
   AND EVSE_ID   = #{v.evseId}
   AND CONN_ID   = #{v.connId}
   AND VAR_NM    = #{v.varNm}
   AND VAR_INST  = #{v.varInst}
   AND ATTR_TP   = #{v.attrTp}

mapper.select:
SELECT CP_ID, CS_ID, COMP_NM, COMP_INST, EVSE_ID, CONN_ID,
       VAR_NM, VAR_INST, ATTR_TP, ATTR_VAL, ATTR_STAT, UPD_DT
  FROM TB_CHCF002
 WHERE CP_ID   = #{cpId}
   AND CS_ID   = #{csId}
   AND COMP_NM = #{compNm}
   AND VAR_NM  = #{varNm}
   AND VAR_INST = #{varInst}
   AND ATTR_TP = #{attrTp}
 LIMIT 1

SELECT CP_ID, CS_ID, COMP_NM, COMP_INST, EVSE_ID, CONN_ID,
       VAR_NM, VAR_INST, ATTR_TP, ATTR_VAL, ATTR_STAT, UPD_DT
  FROM TB_CHCF002
 WHERE CP_ID = #{cpId}
   AND CS_ID = #{csId}
 ORDER BY COMP_NM, EVSE_ID, VAR_NM, ATTR_TP

